hsd:
Driver = GeometryOptimisation {
  Optimiser = LBFGS {}
  LatticeOpt = No
  MaxSteps = 3000
  Convergence { GradElem = 1e-07 }
}
Geometry = GenFormat {
  <<< "geo.gen"
}
Hamiltonian = DFTB {
  SCC = Yes
  SCCTolerance = 1e-10
  MaxSCCIterations = 500
  ShellResolvedSCC = No
  Charge = 0.0
  SlaterKosterFiles = Type2FileNames {
    Prefix = "/tmp/pydftb_dyn_dxubmlt9/plain/"
    Separator = "-"
    Suffix = ".skf"
  }
  MaxAngularMomentum {
    C = "p"
  }
  Filling = Fermi {
    Temperature [K] = 0.0
  }
  KPointsAndWeights = SupercellFolding {
    2 0 0
    0 2 0
    0 0 2
    0.0 0.0 0.0
  }
  Hybrid = LC {
    Screening = MatrixBased {}
  }
  EwaldTolerance = 1e-12

}
Analysis {
  PrintForces = Yes
  MullikenAnalysis = Yes
}
Options {
  WriteDetailedOut = Yes
  WriteResultsTag = Yes
  TimingVerbosity = 0
}
ParserOptions {
  ParserVersion = 14
}
Parallel {
  UseOmpThreads = Yes
}
